"Richtig: η = {} — der Nachweis ist nicht erfüllt.":"Correct: η = {} — the check is not satisfied.",
"Richtig: η = {} — der Nachweis ist erfüllt.":"Correct: η = {} — the check is satisfied.",
"Bitte eine Zahl eingeben.":"Please enter a number.",
"Schritt {} von {}":"Step {} of {}",
"Lösung zeigen":"Show solution",
"Nächster Schritt":"Next step",
"Prüfen":"Check",
"η oder Zwischenwert":"η or intermediate value",
"Deine Ausnutzung η oder ein Zwischenergebnis":"Your utilisation η or an intermediate result",
"Abbildung ausblenden":"Hide figure",
"Abbildung zeigen":"Show figure",
"Übungsmodus: Jeder Schritt zeigt, welche Formel du in welcher Reihenfolge anwendest – die Zahlenwerte sind als „…“ ausgeblendet. Rechne selbst, prüfe dein Ergebnis in den Karten unten oder decke Schritt für Schritt auf.":"Practice mode: each step shows which formula to apply and in which order – the numbers are hidden as “…”. Work it out yourself, check your result in the cards below or reveal the steps one by one.",
"Übungsmodus":"Practice mode",
"Fehler gefunden? Bitte melden.":"Found an error? Please report it.",
"Hinterlüftete Außenschale: {} entfallen (Diffusion und Wärme), R<sub>se</sub> = 0,08 m²K/W":"Rear-ventilated outer leaf: {} disregarded (diffusion and heat), R<sub>se</sub> = 0.08 m²K/W",
"R<sub>T</sub> = ½·R<sub>T,u</sub> + ½·R<sub>T,v</sub> = {} m²K/W → gleichwertig R<sub>Luft</sub> = {} m²K/W":"R<sub>T</sub> = ½·R<sub>T,u</sub> + ½·R<sub>T,v</sub> = {} m²K/W → equivalent R<sub>air</sub> = {} m²K/W",
"ruhend gerechnet R<sub>T,u</sub> = {} · stark belüftet gerechnet R<sub>T,v</sub> = {} m²K/W":"as unventilated R<sub>T,u</sub> = {} · as well ventilated R<sub>T,v</sub> = {} m²K/W",
"Schwach belüftete Luftschicht (DIN EN ISO 6946, 6.9.3, A_v ≈ 1000 mm² je m)":"Slightly ventilated air layer (EN ISO 6946, 6.9.3, A_v ≈ 1000 mm² per m)",
"Die Luftschicht und alle Schichten außerhalb entfallen ({}); außen gilt ruhende Luft: R<sub>se</sub> = R<sub>si</sub> = {} m²K/W":"The air layer and all layers outside it are disregarded ({}); outside, still air applies: R<sub>se</sub> = R<sub>si</sub> = {} m²K/W",
"Stark belüftete Luftschicht (DIN EN ISO 6946, 6.9.4)":"Well-ventilated air layer (EN ISO 6946, 6.9.4)",
"R<sub>{}</sub> = {} m²K/W ({}, gleichwertig aus R<sub>T</sub> — siehe unten)":"R<sub>{}</sub> = {} m²K/W ({}, equivalent from R<sub>T</sub> — see below)",
"R<sub>{}</sub> = {} m²K/W ({}, d = {} mm, {} — DIN EN ISO 6946, Tab. 8)":"R<sub>{}</sub> = {} m²K/W ({}, d = {} mm, {} — EN ISO 6946, Table 8)",
"Wärmestrom nach unten":"heat flow downwards",
"Wärmestrom horizontal":"heat flow horizontal",
"Wärmestrom nach oben":"heat flow upwards",
"R nach Tabelle":"R from table",
"(DIN 4109-32, einschalig massiv)":"(DIN 4109-32, single-leaf solid)",
"Diese Schichten sind durch eine weiche Schicht (ρ < 300 kg/m³) von der massiven Schale getrennt. Das Massegesetz gilt nur für die einschalige Wand; die Wirkung von WDVS oder Vorsatzschalen (ΔR<sub>w</sub> nach DIN 4109-34) ist nicht erfasst.":"These layers are separated from the massive leaf by a soft layer (ρ < 300 kg/m³). The mass law only applies to the single-leaf wall; the effect of ETICS or linings (ΔR<sub>w</sub> to DIN 4109-34) is not included.",
"Nicht angesetzt: {}":"Not included: {}",
"m′ ≥ 100 kg/m² → R<sub>min</sub> = {} m²K/W (DIN 4108-2, Tab. 3)":"m′ ≥ 100 kg/m² → R<sub>min</sub> = {} m²K/W (DIN 4108-2, Table 3)",
"m′ < 100 kg/m²: leichtes Bauteil → R<sub>min</sub> = 1,75 m²K/W (DIN 4108-2, 5.1.2.2)":"m′ < 100 kg/m²: light element → R<sub>min</sub> = 1.75 m²K/W (DIN 4108-2, 5.1.2.2)",
"Flächenbezogene Masse: leichtes oder schweres Bauteil?":"Mass per unit area: light or heavy element?",
"Schallschutz: Es zählen d und ρ der massiven Schale (Massegesetz).":"Sound insulation: d and ρ of the massive leaf count (mass law).",
"Tauwasser: Es zählen d, λ (Temperaturverlauf) und μ (Diffusionswiderstand s<sub>d</sub> = μ·d).":"Condensation: d, λ (temperature profile) and μ (diffusion resistance s<sub>d</sub> = μ·d) count.",
"U-Wert: Es zählen d und λ. ρ geht über die flächenbezogene Masse m′ in den Mindestwärmeschutz ein (leichte Bauteile unter 100 kg/m²: R ≥ 1,75 m²K/W).":"U-value: d and λ count. ρ enters the minimum thermal insulation via the mass per unit area m′ (light elements below 100 kg/m²: R ≥ 1.75 m²K/W).",
"Die Querkraft ist größer als die Schubtragfähigkeit des Stegs (plastisch oder durch Schubbeulen).":"The shear force exceeds the shear resistance of the web (plastic or due to shear buckling).",
"V<sub>Ed</sub> und M<sub>y,Ed</sub> werden im selben Schnitt angesetzt. Beim Einfeldträger liegt max V am Auflager und max M in Feldmitte; wer beide Größtwerte einträgt, liegt auf der sicheren Seite.":"V<sub>Ed</sub> and M<sub>y,Ed</sub> are taken in the same section. For a simply supported beam, max V is at the support and max M at midspan; entering both maxima is on the safe side.",
"Hinweis zur Lage der Schnittgrößen":"Note on where the internal forces act",
"η̄<sub>1</sub> = M<sub>Ed</sub>/M<sub>pl,Rd</sub> = {} < M<sub>f,Rd</sub>/M<sub>pl,Rd</sub> = {}: die Gurte tragen das Moment allein, keine Wechselwirkung":"η̄<sub>1</sub> = M<sub>Ed</sub>/M<sub>pl,Rd</sub> = {} < M<sub>f,Rd</sub>/M<sub>pl,Rd</sub> = {}: the flanges carry the moment alone, no interaction",
"Biegung und Querkraft zusammen (EN 1993-1-5, 7.1)":"Bending and shear together (EN 1993-1-5, 7.1)",
"Nachweis Schubbeulen":"Shear buckling check",
"Anteil der Gurte V<sub>bf,Rd</sub> nicht angesetzt (sichere Seite) → V<sub>b,Rd</sub> = {} kN ≤ η·f<sub>y</sub>·h<sub>w</sub>·t<sub>w</sub>/(√3·γ<sub>M1</sub>) = {} kN":"Flange contribution V<sub>bf,Rd</sub> neglected (safe side) → V<sub>b,Rd</sub> = {} kN ≤ η·f<sub>y</sub>·h<sub>w</sub>·t<sub>w</sub>/(√3·γ<sub>M1</sub>) = {} kN",
"χ<sub>w</sub> = {} = {} (Tab. 5.1, 0,83/η = {})":"χ<sub>w</sub> = {} = {} (Table 5.1, 0.83/η = {})",
"Schubbeulen: Schlankheit und Abminderung (nur Auflagersteifen, verformbarer Endpfosten)":"Shear buckling: slenderness and reduction (stiffeners at supports only, non-rigid end post)",
"kein Beulnachweis nötig, der Steg erreicht V<sub>pl,Rd</sub>":"no buckling check needed, the web reaches V<sub>pl,Rd</sub>",
"Schubbeulen nachweisen":"check shear buckling",
