"Diese Berechnung stammt aus einer älteren Version von „Schnittkräfte“ ohne gespeicherte Verläufe. Bitte in „Schnittkräfte“ neu berechnen und speichern.":"This calculation comes from an older “Internal forces” version without saved diagrams. Please recalculate and save it in “Internal forces”.",
"Kragarm: Zugseite oben, das Moment wird als Betrag übernommen. Biegedrillknicken/Kippen rechnet „Bemessung“ für gabelgelagerte Träger — Lagerung und Kipplänge prüfen.":"Cantilever: tension at the top, the moment is applied as an absolute value. “Design” checks lateral-torsional buckling for fork-supported beams — check the supports and the buckling length.",
"Feldmoment und Stützmoment sind die Größtwerte über alle Felder; die Stützweite ist die des Feldes mit dem größten Feldmoment. Für Stahl und Holz wird der Momentenverlauf als Gleichlast angesetzt — bitte prüfen.":"Span moment and support moment are the maxima over all spans; the span is that of the span with the largest span moment. For steel and timber the moment diagram is taken as a uniform load — please check.",
"Bauphysik rechnet mit dem Bauteilaufbau — aus „Schnittkräfte“ gibt es hier nichts zu übernehmen.":"Building physics works with the element build-up — there is nothing to apply from “Internal forces” here.",
"Wasserbau rechnet mit eigenen Eingaben (Abfluss, Geometrie) — aus „Schnittkräfte“ gibt es hier nichts zu übernehmen.":"Hydraulics works with its own inputs (discharge, geometry) — there is nothing to apply from “Internal forces” here.",
"Für die Stütze braucht „Bemessung“ eine Normalkraft. Die gibt es nur bei Rahmen-Berechnungen (Stiel). Bitte einen Rahmen wählen oder N<sub>Ed</sub> von Hand eingeben.":"For the column, “Design” needs an axial force. Only frame calculations (column) provide it. Please choose a frame or enter N<sub>Ed</sub> by hand.",
"Kein positives Feldmoment: Das Moment wird als Betrag für M<sub>Ed</sub> übernommen — die Zugbewehrung liegt dann oben.":"No positive span moment: the moment is applied as an absolute value for M<sub>Ed</sub> — the tension reinforcement is then at the top.",
"M<sub>qp</sub> (quasi-ständig, für die Rissbreite) kennt „Schnittkräfte“ nicht — bitte von Hand eingeben.":"“Internal forces” does not know M<sub>qp</sub> (quasi-permanent, for the crack width) — please enter it by hand.",
"Platte: Die Werte gelten je Meter Breite, wenn die Lasten in „Schnittkräfte“ je m² eingegeben wurden.":"Slab: the values apply per metre width if the loads were entered per m² in “Internal forces”.",
"Für den Stützenfuß braucht es eine Normalkraft — nur Rahmen-Berechnungen liefern sie.":"The column base needs an axial force — only frame calculations provide it.",
"Für Schweißnähte bitte die Kräfte von Hand eingeben — z. B. M<sub>y,Ed</sub> und V<sub>z,Ed</sub> am Trägerende aus „Schnittkräfte“ für den Fall „Träger an Stirnplatte“.":"For welds, please enter the forces by hand — e.g. M<sub>y,Ed</sub> and V<sub>z,Ed</sub> at the beam end from “Internal forces” for the case “Beam to end plate”.",
"M<sub>y,k</sub> für die Durchbiegung ist charakteristisch — bitte von Hand anpassen.":"M<sub>y,k</sub> for the deflection is characteristic — please adjust by hand.",
"Linearer Momentenverlauf: als „konstant“ angesetzt (sichere Seite).":"Linear moment diagram: taken as “constant” (on the safe side).",
"M<sub>G,k</sub> und M<sub>Q,k</sub> für die Durchbiegung sind charakteristisch — bitte von Hand eingeben.":"M<sub>G,k</sub> and M<sub>Q,k</sub> for the deflection are characteristic — please enter them by hand.",
