"Feuerwiderstand tragender Wände und Stützen (MBO § 27)":"Fire resistance of load-bearing walls and columns (MBO § 27)",
"Fließgeschwindigkeit vor dem Schließen":"Flow velocity before closing",
"Fläche > 0":"Area > 0",
"Freispiegelabfluss nach Gauckler-Manning-Strickler: Vollfüllung, Wassertiefe bei Teilfüllung, Füllungsgrad und Mindestgeschwindigkeit.":"Free-surface flow after Gauckler-Manning-Strickler: full flow, water depth at partial filling, filling ratio and minimum velocity.",
"Förderhöhe der Anlage":"Total head of the plant",
