"Förderhöhe, hydraulische Leistung und Wellenleistung sowie die Haltedruckhöhe NPSH der Anlage mit der zulässigen Saughöhe.":"Total head, hydraulic and shaft power and the net positive suction head NPSH of the plant with the permissible suction lift.",
"Füllungsgrad":"Filling ratio",
"Gebrauchstauglichkeit nach DIN EN 1995-1-1, 7.3: Eigenfrequenz (Frequenzkriterium) und Durchbiegung unter 2 kN (Steifigkeitskriterium) mit der Querverteilung durch den Estrich.":"Serviceability to DIN EN 1995-1-1, 7.3: natural frequency (frequency criterion) and deflection under 2 kN (stiffness criterion) with transverse distribution by the screed.",
