"Gleitkreise (Bishop, Krey), Lamellenverfahren und Bruchmechanismen mit geraden Gleitlinien, Böschungen mit Bermen oder mehreren Schichten, Auflasten an der Böschungskrone und Erdbeben.":"Slip circles (Bishop, Krey), method of slices and failure mechanisms with straight slip lines, slopes with berms or several layers, surcharges at the crest and earthquakes.",
"Grenzzustand HYD: destabilisierende Strömungskraft ≤ stabilisierende Gewichtskraft unter Auftrieb":"Limit state HYD: destabilising seepage force ≤ stabilising submerged weight",
