"Hydrodynamik: Druckwellengeschwindigkeit, Reflexionszeit, Druckstoß nach Joukowsky bzw. Michaud und Vergleich mit der Druckstufe.":"Hydrodynamics: wave speed, reflection time, water hammer after Joukowsky or Michaud and comparison with the pressure rating.",
"Höchst- und Mindestdruck im Rohr":"Maximum and minimum pressure in the pipe",
"Höhere Balken (f<sub>1</sub> ~ h<sup>1,5</sup>), engerer Balkenabstand, kürzere Spannweite oder eine steifere Festigkeitsklasse. Mehr Masse senkt die Frequenz.":"Deeper joists (f<sub>1</sub> ~ h<sup>1.5</sup>), closer joist spacing, shorter span or a stiffer strength class. More mass lowers the frequency.",
