"Langsamer schließen (Schließzeit deutlich über T<sub>r</sub>), Fließgeschwindigkeit senken (größerer Durchmesser), Windkessel oder Druckstoßdämpfer vorsehen oder eine höhere Druckstufe wählen.":"Close more slowly (closing time well above T<sub>r</sub>), reduce the flow velocity (larger diameter), provide a surge vessel or surge damper, or choose a higher pressure rating.",
