"Pumpen- und Anlagenkennlinie (Betriebspunkt), Parallel- und Reihenschaltung, Drehzahlregelung, Anfahr- und Abschaltvorgänge (Druckstoß) und Mindestüberdeckung gegen Lufteintrag (Wirbelbildung).":"Pump and system curves (operating point), parallel and series operation, speed control, start-up and shut-down (water hammer) and minimum submergence against air entrainment (vortices).",
