"Setzung über der Zeit (logarithmisch)":"Settlement over time (logarithmic)",
"Sickerweg um den Wandfuß":"Seepage path around the wall toe",
"Sofortsetzung bei bindigen Böden, Einfluss von Nachbarfundamenten, Schiefstellung bei ausmittiger Last, spannungsabhängiger Steifemodul und Setzungen von Streifenfundamenten mit großem a/b. Den zeitlichen Verlauf rechnet der Modus „Zeitsetzung“.":"Immediate settlement in cohesive soils, influence of neighbouring foundations, tilting under eccentric load, stress-dependent constrained modulus and settlement of strip footings with large a/b. The Consolidation mode calculates the development over time.",
"Sofortsetzung und Kriechsetzung (Sekundärsetzung), mehrere Schichten mit unterschiedlichem c<sub>v</sub>, zeitlich veränderliche Belastung (Bauzeit), radiale Konsolidation bei Vertikaldräns und die Ermittlung von s<sub>∞</sub> (Modus Setzung).":"Immediate and creep settlement (secondary compression), several layers with different c<sub>v</sub>, load varying with time (construction period), radial consolidation with vertical drains and the determination of s<sub>∞</sub> (Settlement mode).",
"Spannweite und Deckenbreite > 0":"Span and floor width > 0",
"Spundwand tiefer einbinden (längerer Sickerweg), Wasserspiegel in der Baugrube höher halten, Auflastfilter auf die Sohle oder Grundwasser absenken.":"Embed the sheet piling deeper (longer seepage path), keep the water level in the excavation higher, place a loaded filter on the base or lower the groundwater.",
