"DIN EN 1996-3/NA, Anhang NA.C, Tab. NA.C.1":"DIN EN 1996-3/NA, Annex NA.C, Table NA.C.1",
"Dachfläche":"Roof surface",
"Der Achsabstand a schützt die Bewehrung: je dicker die Betonschicht, desto länger bleibt der Stahl unter der kritischen Temperatur.":"The axis distance a protects the reinforcement: the thicker the concrete layer, the longer the steel stays below the critical temperature.",
"Der Balken ist für die geforderte Feuerwiderstandsdauer zu schmal — er heizt sich von den Seiten zu schnell durch.":"The beam is too narrow for the required fire resistance — it heats through from the sides too quickly.",
"Der Durchbruch liegt außerhalb der Grenzen für unverstärkte Durchbrüche.":"The hole lies outside the limits for unreinforced holes.",
"Der Queranschluss sitzt zu nah am beanspruchten Rand — das Holz spaltet unter der Querzugkraft.":"The connection sits too close to the loaded edge — the timber splits under the transverse tension.",
"Der Restquerschnitt neben dem Durchbruch ist für die Querkraft zu klein.":"The remaining section next to the hole is too small for the shear force.",
"Der geschwächte Querschnitt ist für das Biegemoment zu klein.":"The weakened section is too small for the bending moment.",
"Dickere Platte oder ein nichtbrennbarer Estrich (zählt zur Dicke h<sub>s</sub>).":"Thicker slab or a non-combustible screed (counts towards the thickness h<sub>s</sub>).",
"Dickere Wand, zusätzliche Halterung (Stütze oder Riegel teilt die Fläche) oder ein rechnerischer Nachweis für Wind.":"Thicker wall, an additional support (a column or rail divides the area) or a calculated wind check.",
"Dickeres oder breiteres Blech bzw. höhere Stahlgüte — die Naht trägt nie mehr als das Blech.":"Thicker or wider plate or a higher steel grade — the weld never carries more than the plate.",
"Dickeres oder breiteres Blech, weniger Schrauben in einer Lochreihe oder kleinere Löcher; eine höhere Stahlgüte hebt f<sub>u</sub>.":"Thicker or wider plate, fewer bolts in one row or smaller holes; a higher steel grade raises f<sub>u</sub>.",
"Die Ausfachungsfläche ist für diese Wanddicke, Halterung und Höhe über Gelände zu groß.":"The infill area is too large for this wall thickness, support and height above ground.",
"Die Betonüberdeckung der Bewehrung ist zu dünn: der Stahl erreicht im Brand zu früh die kritische Temperatur.":"The concrete cover to the reinforcement is too thin: the steel reaches the critical temperature too early in fire.",
"Die Biegespannungen um beide Achsen zusammen übersteigen die Biegefestigkeit.":"The bending stresses about both axes together exceed the bending strength.",
"Die Feldbewehrung reicht für die größte Zugkraft im Feld nicht aus.":"The span reinforcement is not sufficient for the largest tensile force in the span.",
"Die Platte ist zu dünn für die geforderte Feuerwiderstandsdauer (Raumabschluss und Temperatur auf der Oberseite).":"The slab is too thin for the required fire resistance (separating function and temperature on the top surface).",
"Die Querzugkraft an den Ecken des Durchbruchs ist größer als die Querzugfestigkeit des Holzes dort.":"The transverse tension at the corners of the hole is larger than the tensile strength perpendicular to the grain there.",
"Die Schubspannungen aus beiden Richtungen zusammen übersteigen die Schubfestigkeit.":"The shear stresses from both directions together exceed the shear strength.",
"Die Spannungen in der Naht sind größer als ihre Tragfähigkeit.":"The stresses in the weld are larger than its resistance.",
"Die Zugkraft ist größer als die Fließkraft des ungeschwächten Blechs.":"The tensile force is larger than the yield resistance of the unweakened plate.",
"Die lotrechte Last (Eigengewicht, Schnee) wirkt schräg zu den Hauptachsen der Pfette und biegt sie um beide Achsen.":"The vertical load (self-weight, snow) acts at an angle to the principal axes of the purlin and bends it about both axes.",
"Die obere Bewehrung über der Stütze reicht für das Stützmoment nicht aus.":"The top reinforcement over the support is not sufficient for the support moment.",
