"Durchgeschweißte Stumpfnaht als Grundwerkstoff und nicht durchgeschweißte Stumpfnaht wie eine Kehlnaht nach DIN EN 1993-1-8, 4.7.":"Full penetration butt weld as parent metal and partial penetration butt weld like a fillet weld to DIN EN 1993-1-8, 4.7.",
"Durchgeschweißte Stumpfnaht: Tragfähigkeit wie der schwächere Grundwerkstoff (4.7.1) — Nachweis als Blechquerschnitt":"Full penetration butt weld: resistance as the weaker parent metal (4.7.1) — checked as the plate section",
"Ein Blechblock um die Schrauben reißt aus (Zug quer, Schub entlang der Lochreihen).":"A block of plate around the bolts tears out (tension across, shear along the rows of holes).",
"Ein Block reißt aus: Zug auf der Querfläche A<sub>nt</sub>, Schub entlang der Lochreihen A<sub>nv</sub> (zentrische Last)":"A block tears out: tension on the transverse area A<sub>nt</sub>, shear along the rows of holes A<sub>nv</sub> (concentric load)",
"Einseitig nicht durchgeschweißte Nähte nicht durch Biegung um die Nahtlängsachse beanspruchen (Wurzel klafft).":"Do not load single-sided partial penetration welds in bending about the weld axis (the root opens).",
"Einzellasten und ungünstige Laststellungen (Momentengrenzlinie aus mehreren Lastfällen), Schrägstäbe, die Verankerung am Endauflager (Modus Balken), Druckbewehrung und das Abstufen der Stützbewehrung in mehreren Stufen.":"Point loads and unfavourable load arrangements (moment envelope from several load cases), bent-up bars, anchorage at the end support (Beam mode), compression reinforcement and curtailing the support reinforcement in several steps.",
"Feld":"Span",
"Feldbewehrung (größte Zugkraft unten)":"Span reinforcement (largest tension at the bottom)",
"Fließen im Bruttoquerschnitt":"yielding of the gross section",
"Geometrie (NA, NCI NA.6.7, Anhaltswerte für unverstärkte Durchbrüche)":"Geometry (NA, NCI NA.6.7, guide values for unreinforced holes)",
"Geometrie des Anschlusses":"Geometry of the connection",
"Grau gestrichelt: M/z. Orange: um a<sub>l</sub> verschobene Zugkraftlinie. Blau: Deckungslinie der gewählten Stäbe mit Verankerung über l<sub>bd</sub> — sie muss die orange Linie überall umschließen.":"Grey dashed: M/z. Orange: tensile force line shifted by a<sub>l</sub>. Blue: resistance line of the chosen bars with anchorage over l<sub>bd</sub> — it must enclose the orange line everywhere.",
"Grau: Halterungen an Decke, Boden und Stützen. Die Wand trägt nur Wind auf ihre eigene Fläche ab — die Tabelle ersetzt den rechnerischen Nachweis.":"Grey: restraints at floor, ceiling and columns. The wall only carries wind on its own area — the table replaces the calculation.",
"Grenzen für unverstärkte Durchbrüche":"Limits for unreinforced holes",
"Größere Betondeckung (Verlegemaß) oder eine Bekleidung von unten.":"Larger concrete cover or a cladding from below.",
"Größere Betondeckung (Verlegemaß), breiterer Balken (kleinerer Tabellenwert) oder eine Bekleidung, z. B. Putz.":"Larger concrete cover, a wider beam (smaller table value) or a cladding, e.g. plaster.",
"Größere Einbrandtiefe a, durchschweißen oder längere Naht.":"Deeper penetration a, full penetration or a longer weld.",
"Größerer Querschnitt — bei großer Dachneigung lohnt vor allem eine breitere Pfette (W<sub>z</sub> ~ b²) oder eine Zange/Aussteifung in der Dachebene.":"Larger section — with a steep roof a wider purlin pays off most (W<sub>z</sub> ~ b²) or a tie/bracing in the roof plane.",
"Hebelarm, Versatzmaß und Verankerungslängen":"Lever arm, shift rule and anchorage lengths",
"Holz — Durchbruch im Träger":"Timber — hole in the beam",
"Holz — Pfette mit Doppelbiegung":"Timber — purlin in biaxial bending",
"Holz — Querzug am Queranschluss":"Timber — transverse tension at a connection",
"Hängt eine Last unten am Träger, zieht sie die Fasern quer auseinander — je näher der Anschluss am unteren Rand liegt, desto eher spaltet das Holz.":"A load hanging from the bottom of a beam pulls the fibres apart — the closer the connection is to the bottom edge, the sooner the timber splits.",
"Höhe h > 0":"Depth h > 0",
"Höhe und Länge > 0":"Height and length > 0",
"Im durch die Löcher geschwächten Querschnitt reißt das Blech, bevor die Zugkraft erreicht ist.":"In the section weakened by the holes the plate fractures before the tensile force is reached.",
"Keine Tabellenzeile für diese Breite — erst die Mindestbreite einhalten.":"No table row for this width — first satisfy the minimum width.",
"Keine gestaffelten Stäbe eingegeben — die durchlaufenden Stäbe reichen dann nicht.":"No curtailed bars entered — the continuous bars are then not sufficient.",
"Kippen der Pfette (Modus Träger/Stütze), Durchlaufpfetten und Gerberpfetten, Normalkraft aus Windverband, Durchbiegung in zwei Richtungen und Anschlüsse (Pfettenstoß, Auflager).":"Lateral torsional buckling of the purlin (Beam/column mode), continuous and Gerber purlins, axial force from wind bracing, deflection in two directions and connections (purlin splice, supports).",
"Kleinerer Durchbruch, Lage näher an der Trägerachse und weiter weg vom Auflager (kleineres V), höherer Träger oder Verstärkung.":"Smaller hole, closer to the beam axis and further from the support (smaller V), deeper beam or reinforcement.",
