"Zwischen den Halterungen greift keine Querlast an: Die Endmomente kommen aus anschließenden Bauteilen, z. B. Durchlaufträger über der Stütze, Rahmenecke oder Kragarm.":"No transverse load acts between the restraints: the end moments come from adjoining members, e.g. a continuous beam over the support, a frame corner or a cantilever.",
"Gleich große Endmomente: Über die ganze Länge wirkt dasselbe Moment — für das Biegedrillknicken der ungünstigste Fall (C₁ = 1).":"Equal end moments: the same moment acts over the whole length — the most unfavourable case for lateral-torsional buckling (C₁ = 1).",
"Eine Last am Obergurt wirkt beim Kippen zusätzlich destabilisierend, am Untergurt stabilisierend.":"A load on the top flange has an additional destabilising effect on lateral-torsional buckling; on the bottom flange it stabilises.",
