"Der Druckgurt ist durchgehend seitlich gehalten (z. B. durch eine aufliegende Decke) — kein Biegedrillknicken.":"The compression flange is continuously restrained laterally (e.g. by a slab resting on it) — no lateral-torsional buckling.",
